import React, { useEffect, useState } from "react";
import axios from "axios";

function AdminDashboard() {
  const [users, setUsers] = useState([]);

  useEffect(() => {
    fetchUsers();
  }, []);

  const fetchUsers = async () => {
    const res = await axios.get("http://localhost:5000/admin/users");
    setUsers(res.data);
  };

  const updateStatus = async (id, status) => {
    // We send u._id to the server
    await axios.post("http://localhost:5000/admin/update-status", {
      id,
      status,
    });
    fetchUsers();
  };

  return (
    <div style={{ padding: "20px", background: "#f4f4f4", minHeight: "100vh" }}>
      <h2>Admin Dashboard</h2>
      <div style={{ display: "flex", flexWrap: "wrap" }}>
        {users.map((u) => (
          <div
            key={u._id}
            style={{
              border: "1px solid #ccc",
              margin: "10px",
              padding: "15px",
              background: "white",
              borderRadius: "8px",
            }}
          >
            <p>
              <strong>Name:</strong> {u.name}
            </p>
            <p>
              <strong>Status:</strong> {u.payment_status}
            </p>
            {u.payment_screenshot && (
              <img
                src={`http://localhost:5000/uploads/${u.payment_screenshot}`}
                alt="Payment"
                width="150"
                style={{ display: "block", marginBottom: "10px" }}
              />
            )}
            <button
              onClick={() => updateStatus(u._id, "approved")}
              style={{
                background: "green",
                color: "white",
                marginRight: "5px",
              }}
            >
              Approve
            </button>
            <button
              onClick={() => updateStatus(u._id, "rejected")}
              style={{ background: "red", color: "white" }}
            >
              Reject
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
export default AdminDashboard;
